document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("bg-color-picker"),t=document.getElementById("text-component"),o="about-page-paragraph-color";if(!e||!t)return;const n=localStorage.getItem(o);n&&(t.style.backgroundColor=n,e.value=n),e.addEventListener("input",function(){const n=e.value;t.style.backgroundColor=n,localStorage.setItem(o,n)})});